if not doc.custom_customer_id:
    if not doc.gender:
        frappe.throw("Please select Gender before saving the Customer.")

    gender = doc.gender.lower()

    if gender.startswith("f"):
        prefix = "F-"
    elif gender.startswith("m"):
        prefix = "M-"
    else:
        frappe.throw("Gender must be 'Male' or 'Female'.")

    # Find the highest existing number for this prefix
    result = frappe.db.sql("""
        SELECT MAX(CAST(SUBSTRING(custom_customer_id, 3) AS UNSIGNED)) as max_num
        FROM `tabCustomer`
        WHERE custom_customer_id LIKE %s
    """, (prefix + "%",))
    
    next_number = (result[0][0] or 0) + 1
    
    # Format the ID with leading zeros
    doc.custom_customer_id = f"{prefix}{next_number:04d}"

else:
    # Validate existing IDs match gender
    gender = doc.gender.lower()
    if gender.startswith("f") and not doc.custom_customer_id.startswith("F-"):
        frappe.throw("Female customer IDs must start with 'F-'.")
    if gender.startswith("m") and not doc.custom_customer_id.startswith("M-"):
        frappe.throw("Male customer IDs must start with 'M-'.")
